import {SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY} from './config.mjs';
import {loadAll} from './store.mjs';
import {icon} from './icons.mjs';

export function showSettings({state,render,toast}){
  const root=document.querySelector('#settings-content');if(!root)return;
  root.innerHTML=`<section class="section-card"><h2>${icon('database')} Banco público</h2><p>Este CRM não usa login. Qualquer pessoa com o endereço poderá visualizar, importar e atualizar os leads da mesma base.</p><div class="notice blue"><strong>Projeto Supabase conectado</strong><br>${SUPABASE_URL.replace('https://','')}<br><span class="small">Chave pública ${SUPABASE_PUBLISHABLE_KEY.slice(0,18)}…</span></div><div class="form-actions"><a href="/schema.sql" download="mapa-leads-schema-publico.sql"><button>${icon('download')}Baixar schema.sql</button></a><a href="https://supabase.com/dashboard/project/olhytsvxisvlmilphxic/sql/new" target="_blank" rel="noopener noreferrer"><button>${icon('external')}Abrir editor SQL</button></a></div><ol class="setup-steps"><li>Abra o editor SQL do projeto.</li><li>Cole o conteúdo de <strong>schema.sql</strong> e clique em “Run”.</li><li>Volte ao CRM e clique em “Recarregar base”.</li></ol><div class="notice" style="margin-top:18px">O acesso é público por escolha sua. Não use este banco para dados pessoais ou informações confidenciais.</div></section><section class="section-card"><h2>${icon('database')} Estado da conexão</h2><p>${state.demo?'O banco ainda não foi inicializado. Execute o schema acima.':'A base pública está disponível e pronta para receber planilhas.'}</p><div class="form-actions"><button id="reload">${icon('database')}Recarregar base</button></div></section>`;
  root.querySelector('#reload')?.addEventListener('click',async()=>{try{await loadAll(state);toast('Base atualizada.');}catch(err){toast(err.message);}});
}
